// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dur;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.integer;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.str;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.time;

import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of {@code dtf:dateDiff(unit, start, end)} and {@code dtf:dateAdd(dt, duration)}.
 */
class DateDiffAddEdgeCaseTest {

	private final DateDiff dateDiff = new DateDiff();
	private final DateAdd dateAdd = new DateAdd();

	// dateDiff

	@Test
	void reversedOperandsAreNegativeAndEqualOperandsAreZero() {
		assertThat(dateDiff.evaluate(VF, str("day"), date("2024-03-01"), date("2024-01-01"))).isEqualTo(integer(-60));
		assertThat(dateDiff.evaluate(VF, str("second"), dt("2024-01-01T00:00:01"), dt("2024-01-01T00:00:00")))
				.isEqualTo(integer(-1));
		for (String unit : List.of("year", "month", "day", "hour", "second", "millisecond")) {
			assertThat(dateDiff.evaluate(VF, str(unit), dt("2024-02-29T12:00:00Z"), dt("2024-02-29T12:00:00Z")))
					.as(unit)
					.isEqualTo(integer(0));
		}
	}

	@Test
	void yearsAndMonthsAcrossFebruaryTwentyNinthCountCompleteUnits() {
		assertThat(dateDiff.evaluate(VF, str("year"), date("2024-02-29"), date("2025-02-28"))).isEqualTo(integer(0));
		assertThat(dateDiff.evaluate(VF, str("year"), date("2024-02-29"), date("2025-03-01"))).isEqualTo(integer(1));
		assertThat(dateDiff.evaluate(VF, str("year"), date("2024-02-29"), date("2028-02-29"))).isEqualTo(integer(4));
		assertThat(dateDiff.evaluate(VF, str("month"), date("2024-02-29"), date("2024-03-28"))).isEqualTo(integer(0));
		assertThat(dateDiff.evaluate(VF, str("month"), date("2024-02-29"), date("2024-03-29"))).isEqualTo(integer(1));
		assertThat(dateDiff.evaluate(VF, str("month"), date("2024-02-29"), date("2024-02-01"))).isEqualTo(integer(0));
	}

	@Test
	void daysAcrossADaylightSavingChangeUseLiteralOffsets() {
		// no zone rules are applied: with offsets the two values are 23 hours apart, so no complete day has passed
		assertThat(dateDiff.evaluate(VF, str("day"), dt("2024-03-30T12:00:00+01:00"), dt("2024-03-31T12:00:00+02:00")))
				.isEqualTo(integer(0));
		assertThat(dateDiff.evaluate(VF, str("hour"), dt("2024-03-30T12:00:00+01:00"),
				dt("2024-03-31T12:00:00+02:00"))).isEqualTo(integer(23));
		// the same wall-clock values without timezone are a full day apart
		assertThat(dateDiff.evaluate(VF, str("day"), dt("2024-03-30T12:00:00"), dt("2024-03-31T12:00:00")))
				.isEqualTo(integer(1));
		assertThat(dateDiff.evaluate(VF, str("week"), date("2024-01-01"), date("2024-01-14"))).isEqualTo(integer(1));
		assertThat(dateDiff.evaluate(VF, str("week"), date("2024-01-01"), date("2024-01-15"))).isEqualTo(integer(2));
	}

	@Test
	void mixedTimezonesCompareInstants() {
		assertThat(dateDiff.evaluate(VF, str("hour"), dt("2024-01-01T00:00:00+01:00"), dt("2024-01-01T00:00:00Z")))
				.isEqualTo(integer(1));
		assertThat(dateDiff.evaluate(VF, str("minute"), dt("2024-01-01T12:00:00Z"), dt("2024-01-01T12:00:00+05:30")))
				.isEqualTo(integer(-330));
		assertThat(dateDiff.evaluate(VF, str("second"), dt("2024-01-01T00:00:00+00:00"), dt("2024-01-01T00:00:00Z")))
				.isEqualTo(integer(0));
	}

	@Test
	void dateMixedWithDateTimeIsMidnight() {
		// pins current behaviour: an xsd:date operand is midnight (UTC when the other operand has a timezone)
		assertThat(dateDiff.evaluate(VF, str("hour"), date("2024-01-01"), dt("2024-01-01T05:00:00")))
				.isEqualTo(integer(5));
		assertThat(dateDiff.evaluate(VF, str("hour"), date("2024-01-01"), dt("2024-01-01T05:00:00+02:00")))
				.isEqualTo(integer(3));
		assertThat(dateDiff.evaluate(VF, str("minute"), time("10:00:00"), time("10:30:00"))).isEqualTo(integer(30));
	}

	@Test
	void resultIsAnXsdIntegerAndMillisecondsIgnoreSubMillisecondDigits() {
		Literal result = dateDiff.evaluate(VF, str("millisecond"), dt("2024-01-01T00:00:00.000000001"),
				dt("2024-01-01T00:00:01.999999999"));
		assertThat(result.getDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER.getIri());
		assertThat(result).isEqualTo(integer(1999));
		assertThat(dateDiff.evaluate(VF, str("nanosecond"), dt("2024-01-01T00:00:00.000000001"),
				dt("2024-01-01T00:00:01.999999999"))).isEqualTo(integer(1_999_999_998L));
	}

	@Test
	void hugeSpansDoNotOverflow() {
		assertThat(dateDiff.evaluate(VF, str("day"), date("0001-01-01"), date("9999-12-31")))
				.isEqualTo(integer(3_652_058L));
		assertThat(dateDiff.evaluate(VF, str("year"), date("0001-01-01"), date("9999-12-31")))
				.isEqualTo(integer(9998));
		assertThat(dateDiff.evaluate(VF, str("second"), dt("0001-01-01T00:00:00Z"), dt("9999-12-31T00:00:00Z")))
				.isEqualTo(integer(315_537_811_200L));
		assertThat(dateDiff.evaluate(VF, str("millisecond"), dt("0001-01-01T00:00:00Z"), dt("9999-12-31T00:00:00Z")))
				.isEqualTo(integer(315_537_811_200_000L));
	}

	// dateAdd

	@Test
	void monthAndYearAdditionClampsTheDayOfMonth() {
		assertThat(dateAdd.evaluate(VF, dt("2024-01-31T10:00:00Z"), dur("P1M"))).isEqualTo(dt("2024-02-29T10:00:00Z"));
		assertThat(dateAdd.evaluate(VF, date("2024-02-29"), dur("P1Y"))).isEqualTo(date("2025-02-28"));
		assertThat(dateAdd.evaluate(VF, date("2024-02-29"), dur("P4Y"))).isEqualTo(date("2028-02-29"));
		assertThat(dateAdd.evaluate(VF, date("2023-01-31"), dur("P1M"))).isEqualTo(date("2023-02-28"));
	}

	@Test
	void negativeAndZeroDurations() {
		assertThat(dateAdd.evaluate(VF, date("2024-03-01"), dur("-P1D"))).isEqualTo(date("2024-02-29"));
		assertThat(dateAdd.evaluate(VF, dt("2024-03-01T00:00:00Z"), dur("-PT1S")))
				.isEqualTo(dt("2024-02-29T23:59:59Z"));
		Literal unchanged = dt("2024-05-17T10:11:12.5+02:00");
		assertThat(dateAdd.evaluate(VF, unchanged, dur("PT0S"))).isEqualTo(unchanged);
		assertThat(dateAdd.evaluate(VF, unchanged, dur("P0D"))).isEqualTo(unchanged);
	}

	@Test
	void restrictedDurationDatatypesAreAcceptedWhenTheirLexicalFormMatches() {
		assertThat(dateAdd.evaluate(VF, date("2024-01-31"),
				VF.createLiteral("P1M", CoreDatatype.XSD.YEARMONTHDURATION))).isEqualTo(date("2024-02-29"));
		assertThat(dateAdd.evaluate(VF, dt("2024-01-01T00:00:00"),
				VF.createLiteral("PT1H", CoreDatatype.XSD.DAYTIMEDURATION))).isEqualTo(dt("2024-01-01T01:00:00"));
		assertEvaluationError("time part in a yearMonthDuration", () -> dateAdd.evaluate(VF, date("2024-01-31"),
				VF.createLiteral("PT1H", CoreDatatype.XSD.YEARMONTHDURATION)));
		assertEvaluationError("month part in a dayTimeDuration", () -> dateAdd.evaluate(VF, date("2024-01-31"),
				VF.createLiteral("P1M", CoreDatatype.XSD.DAYTIMEDURATION)));
	}

	@Test
	void timePartsOnDatesAndDayPartsOnTimes() {
		// pins current behaviour: for an xsd:date the time part of the duration is ignored (no promotion to
		// dateTime), and for an xsd:time the day part is ignored while hours wrap around midnight
		assertThat(dateAdd.evaluate(VF, date("2024-01-01"), dur("PT1H"))).isEqualTo(date("2024-01-01"));
		assertThat(dateAdd.evaluate(VF, date("2024-01-01"), dur("PT23H59M59S"))).isEqualTo(date("2024-01-01"));
		assertThat(dateAdd.evaluate(VF, date("2024-01-01"), dur("P1DT1H"))).isEqualTo(date("2024-01-02"));
		assertThat(dateAdd.evaluate(VF, time("10:00:00"), dur("P1D"))).isEqualTo(time("10:00:00"));
		assertThat(dateAdd.evaluate(VF, time("10:00:00"), dur("P1M"))).isEqualTo(time("10:00:00"));
		assertThat(dateAdd.evaluate(VF, time("10:00:00"), dur("PT25H"))).isEqualTo(time("11:00:00"));
		assertThat(dateAdd.evaluate(VF, time("00:30:00+01:00"), dur("-PT1H"))).isEqualTo(time("23:30:00+01:00"));
	}

	@Test
	void fractionalSecondsInTheDuration() {
		assertThat(dateAdd.evaluate(VF, dt("2024-01-01T00:00:00"), dur("PT0.5S")))
				.isEqualTo(dt("2024-01-01T00:00:00.5"));
		assertThat(dateAdd.evaluate(VF, dt("2024-01-01T00:00:00"), dur("PT0.000000001S")))
				.isEqualTo(dt("2024-01-01T00:00:00.000000001"));
		// pins current behaviour: digits beyond nanoseconds are dropped
		assertThat(dateAdd.evaluate(VF, dt("2024-01-01T00:00:00"), dur("PT0.0000000001S")))
				.isEqualTo(dt("2024-01-01T00:00:00"));
		assertThat(dateAdd.evaluate(VF, dt("2024-01-01T00:00:00.75"), dur("PT0.75S")))
				.isEqualTo(dt("2024-01-01T00:00:01.5"));
	}

	@Test
	void yearsBeyondFourDigitsAreValidAndOnlyTheRealRangeLimitIsAnError() {
		// pins current behaviour: XSD allows years outside 0001-9999 and so does dateAdd; the family-wide contract
		// requires year > 9999 to work, so no error is raised at the four-digit boundary
		assertThat(dateAdd.evaluate(VF, date("9999-12-31"), dur("P1D"))).isEqualTo(date("10000-01-01"));
		assertThat(dateAdd.evaluate(VF, date("-9999-01-01"), dur("-P1D"))).isEqualTo(date("-10000-12-31"));
		// the supported range ends where java.time's does
		assertEvaluationError("beyond max year", () -> dateAdd.evaluate(VF, date("999999999-12-31"), dur("P1D")));
		assertEvaluationError("below min year",
				() -> dateAdd.evaluate(VF, date("-999999999-01-01"), dur("-P1D")));
	}

	@Test
	void addingADayKeepsTheLiteralOffsetAcrossDaylightSaving() {
		assertThat(dateAdd.evaluate(VF, dt("2024-03-30T12:00:00+01:00"), dur("P1D")))
				.isEqualTo(dt("2024-03-31T12:00:00+01:00"));
		assertThat(dateAdd.evaluate(VF, dt("2024-10-26T12:00:00+02:00"), dur("P1D")))
				.isEqualTo(dt("2024-10-27T12:00:00+02:00"));
	}
}
